// This script was generated by the Isolines extension's dialog ('Generate code').
// It reproduces, as a re-runnable script, what the dialog's 'Generate isolines' button
// would do directly -- useful for batch-processing a project, or for tweaking the
// settings below by hand.

import qupath.ext.isolines.Isolines

// --- Settings chosen in the Isolines dialog ---

// Path to the density map (heatmap) JSON file, as saved from QuPath's 'Load density map'
// dialog or a density map builder script. Backslashes are escaped below so this survives
// as a Groovy string literal on Windows paths.
def densityMapPath = java.nio.file.Paths.get(
    "{{HEATMAP_PATH}}")

// Channel of the density map to threshold (0 = first channel; only matters if the map
// has more than one -- see Isolines' class docs).
def channel = {{CHANNEL}}

// Number of evenly-spaced isoline levels to generate across the density map's own
// display range (endpoints excluded -- see Isolines.computeLevels).
def nLevels = {{N_LEVELS}}

// Simplification tolerance, in pixels. If > 0, each isoline is run through
// TopologyPreservingSimplifier at this tolerance immediately after it's created, to smooth
// out raw pixel-boundary jaggedness -- see Isolines.createIsolines. 0 leaves geometry exactly
// as thresholding produced it.
def simplifyTolerance = {{SIMPLIFY_TOLERANCE}}

def imageData = getCurrentImageData()
def hierarchy = imageData.getHierarchy()

{{CLEAR_BLOCK}}
{{MASK_BLOCK}}
// Create the isoline annotations. Each level becomes its own PathClass named
// "Isoline <value>", coloured using the density map's own colormap/display range so
// isoline colours match whatever the raster preview would have looked like.
Isolines.createIsolinesFromJson(imageData, densityMapPath, channel, nLevels, maskObjects, simplifyTolerance)

// --- Optional further cleanup: remove small islands / holes ---
// Simplification (above) only smooths jagged boundaries -- it doesn't drop small isolated
// fragments or holes. If you're seeing lots of those, uncomment the block below to remove
// anything smaller than the given area (in pixels^2) via GeometryTools.refineAreas.
//
// Note this matches by class-name *prefix* ("Isoline "), not equality: every level gets
// its own distinct class name (e.g. "Isoline 5.000"), so matching on the exact string
// "Isoline" alone -- as in an earlier draft of this script -- would never match anything.
